def biGraph(n, e, arr):
    from collections import defaultdict

    graph = defaultdict(list)
    for i in range(0, 2*e, 2):
        u, v = arr[i], arr[i+1]
        graph[u].append(v)
        graph[v].append(u)

    disc = [-1] * n
    low = [-1] * n
    time = 0
    is_biconnected = True

    def dfs(u, parent):
        nonlocal time, is_biconnected
        disc[u] = low[u] = time
        time += 1
        children = 0

        for v in graph[u]:
            if disc[v] == -1:
                children += 1
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if parent != -1 and low[v] >= disc[u]:
                    is_biconnected = False
            elif v != parent:
                low[u] = min(low[u], disc[v])

        if parent == -1 and children > 1:
            pass
        elif parent != -1 and low[u] >= disc[parent]:
            is_biconnected = False

    for i in range(n):
        if disc[i] == -1:
            dfs(i, -1)
            if not is_biconnected:
                return 0

    return 1
